export type Task = { id:string; title:string; description:string; state:string; revision:number; createdAt:string; updatedAt:string; deletedAt:string|null; fields:Record<string,string> };
export type Field = { key:string; label:string; type:"text"; required?:boolean; description?:string };
export type WorkflowDefinition = { id:string; name:string; version:string; initialState:string; states:Record<string,{label:string;category:"open"|"done"}>; actions:{id:string;label:string;from:string[]}[]; fields:Field[] };
export type WorkflowDecision = {kind:"reject";message:string}|{kind:"input-required";fields:Field[]}|{kind:"commit";state:string;fields:Record<string,string>};

export default {
  describe(): WorkflowDefinition {
    return {
      id: "default",
      name: "轻快完成",
      version: "1.0.0",
      initialState: "open",
      states: {
        open: { label: "未完成", category: "open" },
        done: { label: "已完成", category: "done" },
      },
      actions: [
        { id: "complete", label: "完成", from: ["open"] },
        { id: "reopen", label: "重新打开", from: ["done"] },
      ],
      fields: [
        { key: "reflection", label: "复盘", type: "text", required: true }
      ],
    };
  },
  decide(data: { task: Task; action: string; input: Record<string, string> }): WorkflowDecision {
    const { task, action, input } = data;
    const def = this.describe();
    const actionDef = def.actions.find(a => a.id === action);

    if (!actionDef || !actionDef.from.includes(task.state)) {
      return { kind: "reject", message: "当前状态不能执行此操作" };
    }

    if (action === "complete") {
      const rawReflection = input.reflection || "";
      const reflection = rawReflection.trim();
      const codePoints = Array.from(reflection).length;

      if (codePoints < 1 || codePoints > 5000) {
        return { kind: "input-required", fields: def.fields };
      }

      return {
        kind: "commit",
        state: "done",
        fields: { ...task.fields, reflection }
      };
    }

    if (action === "reopen") {
      return {
        kind: "commit",
        state: "open",
        fields: task.fields,
      };
    }

    return { kind: "reject", message: "未知操作" };
  }
};

